namespace TracLabs.Domain.Entities;

/// <summary>
/// Represents a formal calibration certificate issued to a client.
/// A certificate is the final, externally-visible output of the calibration process.
/// Each certificate corresponds to exactly one CalibrationRecord.
/// </summary>
public class Certificate : BaseEntity
{
    // ── Identity ──────────────────────────────────────────────────────────────

    /// <summary>
    /// The unique, sequential certificate number visible to clients and auditors.
    /// Format: CERT-YYYY-NNNNN (e.g. "CERT-2025-00042").
    /// Generated by ICertificateRepository.GenerateNextCertificateNumberAsync().
    /// </summary>
    public string CertificateNumber { get; private set; } = string.Empty;

    // ── Links ─────────────────────────────────────────────────────────────────

    /// <summary>The calibration record this certificate documents.</summary>
    public Guid CalibrationRecordId { get; private set; }
    public CalibrationRecord? CalibrationRecord { get; private set; }

    // ── Lifecycle ─────────────────────────────────────────────────────────────

    public CertificateStatus Status { get; private set; } = CertificateStatus.Draft;

    /// <summary>When the certificate was formally issued (signed and delivered).</summary>
    public DateTime? IssuedAt { get; private set; }

    /// <summary>
    /// The user ID of whoever approved and issued this certificate.
    /// In many labs this is a supervisor, not the technician who calibrated.
    /// </summary>
    public string? IssuedByUserId { get; private set; }

    // ── PDF Storage ───────────────────────────────────────────────────────────

    /// <summary>
    /// The generated PDF file stored as binary.
    /// Storing in the database keeps the certificate tightly coupled to its record
    /// and simplifies backup. For high-volume production use, this could move to
    /// blob storage, but for a prototype this approach is perfectly valid.
    /// </summary>
    public byte[]? PdfContent { get; private set; }

    /// <summary>File name for download, e.g. "CERT-2025-00042.pdf".</summary>
    public string? PdfFileName { get; private set; }

    // ── Constructors ──────────────────────────────────────────────────────────

    private Certificate() { }

    public Certificate(string certificateNumber, Guid calibrationRecordId)
    {
        if (string.IsNullOrWhiteSpace(certificateNumber))
            throw new ArgumentException(
                "Certificate number cannot be empty.", nameof(certificateNumber));

        CertificateNumber = certificateNumber;
        CalibrationRecordId = calibrationRecordId;
        Status = CertificateStatus.Draft;
    }

    // ── Domain Methods ────────────────────────────────────────────────────────

    /// <summary>
    /// Attaches the generated PDF binary to this certificate.
    /// Called by the PDF generation service after QuestPDF renders the document.
    /// </summary>
    public void AttachPdf(byte[] pdfContent, string fileName)
    {
        if (pdfContent == null || pdfContent.Length == 0)
            throw new ArgumentException("PDF content cannot be empty.", nameof(pdfContent));

        PdfContent = pdfContent;
        PdfFileName = fileName;
        MarkAsUpdated();
    }

    /// <summary>
    /// Formally issues the certificate, making it the official document.
    /// Once issued, a certificate cannot be modified — a new one must be created.
    /// </summary>
    public void Issue(string issuedByUserId)
    {
        if (Status != CertificateStatus.Draft)
            throw new InvalidOperationException(
                $"Cannot issue a certificate that is in status '{Status}'.");
        if (PdfContent == null)
            throw new InvalidOperationException(
                "Cannot issue a certificate without an attached PDF.");

        Status = CertificateStatus.Issued;
        IssuedAt = DateTime.UtcNow;
        IssuedByUserId = issuedByUserId;
        MarkAsUpdated();
    }

    /// <summary>
    /// Supersedes this certificate, typically because an error was found
    /// and a corrected certificate was issued in its place.
    /// </summary>
    public void Supersede()
    {
        if (Status != CertificateStatus.Issued)
            throw new InvalidOperationException("Only issued certificates can be superseded.");

        Status = CertificateStatus.Superseded;
        MarkAsUpdated();
    }
}